from html.parser import HTMLParser
from pathlib import Path
html = Path('.next/server/app/index.html').read_text()
class MainText(HTMLParser):
    def __init__(self):
        super().__init__(); self.depth = 0; self.text = []
    def handle_starttag(self, tag, attrs):
        if tag == 'main': self.depth += 1
    def handle_endtag(self, tag):
        if tag == 'main': self.depth -= 1
    def handle_data(self, data):
        if self.depth and data.strip(): self.text.append(data.strip())
p = MainText(); p.feed(html)
print('Static <main> text:', ' | '.join(p.text))
expected = ['Dashboard', 'Total Revenue', 'Total Invoices', 'Revenue', 'Latest Invoices', 'Loading revenue...', 'Loading invoice count...', 'Loading chart...', 'Loading invoices...']
assert all(item in p.text for item in expected), 'Missing dashboard shell content'
print('Static shell assertion: passed')
PY

